/* From Uiverse.io by laminelawal - Tags: input, html */
.__UIV_SCOPE__ .input {
  padding: 10px;
  width: 120px;
  border: none;
  outline: none;
  border-radius: 5px;
  box-shadow: 0 1px  gray;
  font-size: 18px;
  transition: width 0.3s;
  font-family: Consolas,monaco,monospace;
}

.__UIV_SCOPE__ .input:focus {
  outline: 1px solid blue;
  box-shadow: none;
  width: 230px;
}

.__UIV_SCOPE__ .input::placeholder {
  color: blue;
}
